mapper.select:
SELECT m.id AS id, m.user_id AS userId, u.username AS username, u.display_name AS displayName, m.role AS role, m.created_at AS createdAt FROM wb_project_group_member m INNER JOIN wb_user u ON m.user_id = u.id WHERE m.group_id = #{groupId}
AND (LOWER(u.username) LIKE #{kw} OR LOWER(u.display_name) LIKE #{kw})
ORDER BY m.role ASC, m.created_at ASC
